const HT_BREITE = 78;
const htUmbruch = (text, einzug, breite) => {
  const platz = Math.max(20, (breite || HT_BREITE) - einzug.length);
  const raus = [];
  String(text === undefined || text === null ? '' : text).replace(/\r/g, '').split('\n').forEach(absatz => {
    const worte = absatz.trim().split(/\s+/).filter(Boolean);
    if (!worte.length) {
      raus.push('');
      return;
    }
    let zeile = '';
    worte.forEach(wort => {
      if (!zeile) {
        zeile = wort;
        return;
      }
      if (zeile.length + 1 + wort.length <= platz) {
        zeile += ' ' + wort;
        return;
      }
      raus.push(einzug + zeile);
      zeile = wort;
    });
    raus.push(einzug + zeile);
  });
  while (raus.length && !raus[0]) raus.shift();
  while (raus.length && !raus[raus.length - 1]) raus.pop();
  return raus;
};
